<script setup lang="ts">
import { Search, ArrowRight, Boxes, Thermometer, Waves, Ruler, Settings2, Grid3X3, Play, RotateCcw, CheckCircle2, AlertTriangle, ChevronRight, Activity, ShieldCheck, Download, FileJson, BarChart3, CircleDot, Layers3 } from 'lucide-vue-next'
import { caeTools } from '~/utils/content'
import { solveBarStatic, solveCantileverBeam, solveSteadyHeat2D, solveSdofModal, type AnyCaeResult } from '~/utils/caeSolvers'

const route = useRoute(), router = useRouter(), store = usePlatformStore()
const listRoute = computed(() => route.path === '/cae')
const resultRoute = computed(() => route.path.startsWith('/cae/tasks/'))
const slug = computed(() => route.path.split('/')[2] || '')
const tool = computed(() => caeTools.find(item => item.slug === slug.value))
const taskId = computed(() => route.path.split('/').at(-1) || '')
const task = computed(() => store.tasks.find(item => item.id === taskId.value))
const result = computed(() => (task.value?.result || null) as unknown as AnyCaeResult | null)
const query = ref(''), discipline = ref('全部领域')
const filteredTools = computed(() => caeTools.filter(item => (discipline.value === '全部领域' || item.discipline === discipline.value) && (!query.value || `${item.name}${item.description}${item.discipline}`.toLowerCase().includes(query.value.toLowerCase()))))
const icons = { 'axial-bar': Ruler, 'cantilever-beam': Boxes, 'heat-plate': Thermometer, 'sdof-modal': Waves }

const defaults: Record<string, Record<string, number>> = {
  'axial-bar': { length: 1, area: .0004, elasticModulus: 2.1e11, elements: 10, endLoad: 20000, distributedLoad: 0 },
  'cantilever-beam': { length: 2, elasticModulus: 2.1e11, secondMoment: 8.333e-6, elements: 12, tipLoad: -1000, uniformLoad: 0, tipMoment: 0 },
  'heat-plate': { width: 1, height: .6, conductivity: 45, nx: 31, ny: 21, heatSource: 0, leftTemperature: 373.15, rightTemperature: 293.15, tolerance: 1e-7, maxIterations: 12000, relaxation: 1.5 },
  'sdof-modal': { mass: 10, stiffness: 4000 }
}
const params = reactive<Record<string, number>>({})
const stages = [{ id: 'definition', label: '分析定义', icon: Settings2 }, { id: 'model', label: '几何与材料', icon: Boxes }, { id: 'mesh', label: '离散与网格', icon: Grid3X3 }, { id: 'solve', label: '装配与求解', icon: Activity }, { id: 'results', label: '结果与验证', icon: BarChart3 }]
const activeStage = ref('definition'), modelReady = ref(false), meshReady = ref(false), running = ref(false), progress = ref(0), phase = ref('等待提交')
const modelSnapshot = ref(''), meshSnapshot = ref('')
const caseName = ref('')
const fields = computed(() => ({
  'axial-bar': [['length','杆长','m',.001,1000],['area','截面积','m²',1e-9,10],['elasticModulus','弹性模量','Pa',1,1e13],['elements','单元数','—',1,200],['endLoad','端部载荷','N',-1e12,1e12],['distributedLoad','分布载荷','N/m',-1e12,1e12]],
  'cantilever-beam': [['length','梁长','m',.001,1000],['elasticModulus','弹性模量','Pa',1,1e13],['secondMoment','截面惯性矩','m⁴',1e-14,100],['elements','梁单元数','—',1,160],['tipLoad','端部集中力','N',-1e12,1e12],['uniformLoad','均布载荷','N/m',-1e12,1e12],['tipMoment','端部力矩','N·m',-1e12,1e12]],
  'heat-plate': [['width','板宽','m',.001,1000],['height','板高','m',.001,1000],['conductivity','导热系数','W/(m·K)',1e-9,1e6],['nx','x 节点','—',3,151],['ny','y 节点','—',3,151],['heatSource','体积热源','W/m³',-1e12,1e12],['leftTemperature','左边界温度','K',0,5000],['rightTemperature','右边界温度','K',0,5000],['tolerance','收敛容差','K',1e-12,.1],['maxIterations','最大迭代','—',1,100000],['relaxation','松弛因子','—',.1,1.95]],
  'sdof-modal': [['mass','质量','kg',1e-12,1e12],['stiffness','刚度','N/m',0,1e15]]
}[slug.value] || []) as Array<[string,string,string,number,number]>)
const meshKeys = ['elements','nx','ny']
const modelFields = computed(() => fields.value.filter(item => !meshKeys.includes(item[0])))
const meshFields = computed(() => fields.value.filter(item => meshKeys.includes(item[0])))
const paramsValid = computed(() => fields.value.every(([key,,,min,max]) => Number.isFinite(Number(params[key])) && Number(params[key]) >= min && Number(params[key]) <= max && (!meshKeys.includes(key) || Number.isInteger(Number(params[key])))))
const modelSignature = computed(() => JSON.stringify(Object.fromEntries(modelFields.value.map(item => [item[0], params[item[0]]]))))
const meshSignature = computed(() => JSON.stringify({ model: modelSignature.value, mesh: Object.fromEntries(meshFields.value.map(item => [item[0], params[item[0]]])) }))
const dofCount = computed(() => slug.value === 'cantilever-beam' ? (Number(params.elements || 1) + 1) * 2 : slug.value === 'axial-bar' ? Number(params.elements || 1) + 1 : slug.value === 'heat-plate' ? Number(params.nx || 1) * Number(params.ny || 1) : 1)
const canRun = computed(() => paramsValid.value && modelReady.value && meshReady.value && !running.value)
const fieldGroups = computed(() => activeStage.value === 'mesh' ? meshFields.value : modelFields.value)

function reset() { Object.assign(params, defaults[slug.value] || {}); caseName.value = `${tool.value?.name || 'CAE'} · 基准算例`; activeStage.value = 'definition'; modelReady.value = false; meshReady.value = slug.value === 'sdof-modal'; modelSnapshot.value = ''; meshSnapshot.value = ''; progress.value = 0; phase.value = '等待提交' }
function confirmModel() { if (!paramsValid.value) return; modelReady.value = true; modelSnapshot.value = modelSignature.value; meshReady.value = slug.value === 'sdof-modal'; if (meshReady.value) meshSnapshot.value = meshSignature.value; activeStage.value = meshReady.value ? 'solve' : 'mesh' }
function generateMesh() { if (!modelReady.value || !paramsValid.value) return; meshReady.value = true; meshSnapshot.value = meshSignature.value; activeStage.value = 'solve' }
function status(id:string) { const index=stages.findIndex(item=>item.id===id), active=stages.findIndex(item=>item.id===activeStage.value); return index<active?'complete':id===activeStage.value?'current':'pending' }
function solveCase(): AnyCaeResult {
  if (slug.value === 'axial-bar') return solveBarStatic(params as any)
  if (slug.value === 'cantilever-beam') return solveCantileverBeam(params as any)
  if (slug.value === 'heat-plate') return solveSteadyHeat2D({ width:params.width,height:params.height,conductivity:params.conductivity,nx:params.nx,ny:params.ny,heatSource:params.heatSource,tolerance:params.tolerance,maxIterations:params.maxIterations,relaxation:params.relaxation,boundaries:{left:{type:'temperature',value:params.leftTemperature},right:{type:'temperature',value:params.rightTemperature},top:{type:'flux',value:0},bottom:{type:'flux',value:0}} })
  return solveSdofModal({ mass: params.mass, stiffness: params.stiffness })
}
async function run() {
  if (!canRun.value || !tool.value) return
  running.value = true; progress.value = 8; phase.value = '检查约束与材料'; const started = performance.now()
  const disciplineMap = { '结构静力':'STRUCTURAL', '热分析':'THERMAL', '模态分析':'MODAL' } as const
  const created = store.addTask({ tool: tool.value.slug, toolName: tool.value.name, params:{...params,case_name:caseName.value}, discipline: disciplineMap[tool.value.discipline as keyof typeof disciplineMap] })
  for (const [label,value] of [['生成节点与单元',25],['装配全局方程',48],['施加边界条件',63],['数值求解',82],['平衡与参考解校核',100]] as const) { phase.value=label; await new Promise(resolve=>setTimeout(resolve,120)); progress.value=value }
  try { const solved=solveCase(); if (!solved.validation.valid || !solved.data) throw new Error(solved.validation.issues.map(item=>item.message).join('；') || '输入校验失败'); store.finishTask(created.id, solved as unknown as Record<string,unknown>, solved.warnings, performance.now()-started); running.value=false; activeStage.value='results'; await router.push(`/cae/tasks/${created.id}`) }
  catch(error) { running.value=false; phase.value='求解失败'; store.failTask(created.id,error instanceof Error?error.message:'求解失败',performance.now()-started) }
}
function downloadJson(){if(!task.value)return;const blob=new Blob([JSON.stringify({task:task.value,result:result.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${task.value.id}-cae.json`;a.click();URL.revokeObjectURL(url)}
watch(slug, reset, { immediate:true }); watch(modelSignature, value=>{if(modelSnapshot.value&&value!==modelSnapshot.value){modelReady.value=false;meshReady.value=false}}); watch(meshSignature,value=>{if(meshSnapshot.value&&value!==meshSnapshot.value)meshReady.value=false}); onMounted(()=>store.init())
</script>

<template>
  <div v-if="listRoute" class="page cae-page"><section class="page-hero cae-hero"><div class="container"><span class="kicker">CAE ANALYSIS STUDIO</span><h1>结构、热与模态的可验证计算</h1><p>用真实单元组装、方程求解、反力或能量平衡与解析解校核，完成适合浏览器规模的工程分析。</p><div class="cae-boundary-note"><ShieldCheck :size="17"/><span><strong>能力边界清晰</strong>当前支持小规模线性分析；不宣称支持三维 CAD、接触、塑性或大型稀疏求解。</span></div></div></section><div class="container cae-catalog"><div class="cae-filterbar"><div class="page-search"><Search :size="17"/><input v-model="query" placeholder="搜索结构、热或模态分析…"></div><div><button v-for="item in ['全部领域','结构静力','热分析','模态分析']" :key="item" :class="{active:discipline===item}" @click="discipline=item">{{item}}</button></div></div><section class="cae-tool-grid"><NuxtLink v-for="(item,index) in filteredTools" :key="item.slug" :to="`/cae/${item.slug}`"><header><span><component :is="icons[item.slug as keyof typeof icons]" :size="23"/></span><i>0{{index+1}}</i></header><small>{{item.discipline}} · {{item.dimension}}</small><h2>{{item.name}}</h2><p>{{item.description}}</p><div class="cae-method-chain"><span>建模</span><i></i><span>离散</span><i></i><span>求解</span><i></i><span>验证</span></div><footer><span>{{item.level}}</span><strong>创建分析 <ArrowRight :size="16"/></strong></footer></NuxtLink></section></div></div>

  <div v-else-if="!resultRoute && tool" class="page cae-workbench-page"><div class="container breadcrumb"><NuxtLink to="/cae">CAE 仿真</NuxtLink><ChevronRight :size="14"/><span>{{tool.name}}</span></div><header class="container cae-case-head"><div><span class="status-badge success"><CircleDot :size="14"/>本地确定性求解</span><input v-model="caseName" aria-label="分析名称"><p>{{tool.discipline}} · {{tool.description}}</p></div><dl><div><dt>自由度</dt><dd>{{dofCount}}</dd></div><div><dt>状态</dt><dd>{{canRun?'可求解':'配置中'}}</dd></div></dl></header><nav class="container cae-stepper"><button v-for="(stage,index) in stages" :key="stage.id" :class="[status(stage.id),{active:activeStage===stage.id}]" :disabled="stage.id==='results'" @click="activeStage=stage.id"><span><CheckCircle2 v-if="status(stage.id)==='complete'" :size="16"/><component :is="stage.icon" v-else :size="16"/></span><div><small>0{{index+1}}</small><strong>{{stage.label}}</strong></div></button></nav><div class="container cae-workbench"><aside class="cae-tree"><div class="studio-panel-title"><Layers3 :size="16"/><strong>分析树</strong></div><button v-for="stage in stages.slice(0,4)" :key="stage.id" :class="{active:activeStage===stage.id}" @click="activeStage=stage.id"><component :is="stage.icon" :size="15"/><span><strong>{{stage.label}}</strong><small>{{stage.id==='mesh'?`${dofCount} DOF`:status(stage.id)==='complete'?'已确认':'待配置'}}</small></span><CheckCircle2 v-if="status(stage.id)==='complete'" :size="14"/></button><div class="cae-tree-note"><ShieldCheck :size="16"/><span><strong>验证基线</strong><small>平衡 · 残差 · 解析解</small></span></div></aside><main class="cae-main"><div class="viewport-toolbar"><div><strong>{{stages.find(item=>item.id===activeStage)?.label}}</strong><span>{{tool.dimension}} · {{tool.discipline}}</span></div><span class="cae-dof-chip">{{dofCount}} DOF</span></div><CaeViewport :kind="slug" :stage="activeStage" :params="params"/><section class="cae-stage-copy"><span class="kicker">{{activeStage==='mesh'?'DISCRETIZATION':activeStage==='solve'?'ASSEMBLY & SOLUTION':'MODEL DEFINITION'}}</span><h2>{{activeStage==='mesh'?'生成实际节点与单元':activeStage==='solve'?'装配方程并执行校核':'定义物理对象与边界条件'}}</h2><p>{{activeStage==='mesh'?'网格参数会决定实际方程规模；修改几何或材料后，下游网格状态会自动失效。':activeStage==='solve'?'求解完成后自动检查力/能量平衡、数值残差以及可用的解析参考解。':'所有输入都经过有限值、量纲范围和拓扑约束校验。'}}</p></section></main><aside class="cae-properties"><div class="studio-panel-title"><Settings2 :size="16"/><strong>属性</strong><button @click="reset"><RotateCcw :size="14"/></button></div><form @submit.prevent="run"><template v-if="activeStage==='definition'||activeStage==='model'"><div class="cae-field-grid"><label v-for="field in fieldGroups" :key="field[0]">{{field[1]}}<div class="unit-input"><input v-model.number="params[field[0]]" type="number" :min="field[3]" :max="field[4]" step="any"><span>{{field[2]}}</span></div><small>{{field[3]}} – {{field[4]}}</small></label></div><button type="button" class="button full" :disabled="!paramsValid" @click="confirmModel">确认模型 <ArrowRight :size="16"/></button></template><template v-else-if="activeStage==='mesh'"><div v-if="meshFields.length" class="cae-field-grid"><label v-for="field in meshFields" :key="field[0]">{{field[1]}}<div class="unit-input"><input v-model.number="params[field[0]]" type="number" :min="field[3]" :max="field[4]" step="1"><span>{{field[2]}}</span></div></label></div><div class="cae-mesh-report"><span><small>方程规模</small><strong>{{dofCount}} DOF</strong></span><span><small>离散类型</small><strong>{{slug==='heat-plate'?'规则有限差分':slug==='sdof-modal'?'集中参数':'线性有限元'}}</strong></span></div><button type="button" class="button full" :disabled="!modelReady" @click="generateMesh"><Grid3X3 :size="16"/>生成离散系统</button></template><template v-else><div class="cae-preflight"><div :class="{pass:paramsValid}"><CheckCircle2 v-if="paramsValid" :size="16"/><AlertTriangle v-else :size="16"/><span><strong>输入与量纲</strong><small>{{paramsValid?'全部参数有效':'存在越界参数'}}</small></span></div><div :class="{pass:modelReady}"><CheckCircle2 v-if="modelReady" :size="16"/><AlertTriangle v-else :size="16"/><span><strong>模型约束</strong><small>{{modelReady?'已确认':'需要重新确认'}}</small></span></div><div :class="{pass:meshReady}"><CheckCircle2 v-if="meshReady" :size="16"/><AlertTriangle v-else :size="16"/><span><strong>离散系统</strong><small>{{meshReady?`${dofCount} DOF`:'尚未生成'}}</small></span></div></div><div v-if="running" class="cae-progress"><strong>{{phase}}</strong><span>{{progress}}%</span><div class="progress"><i :style="{width:progress+'%'}"></i></div></div><button type="submit" class="button full large" :disabled="!canRun"><Play :size="17"/>装配并求解</button></template></form></aside></div></div>

  <div v-else-if="resultRoute && task && result?.data" class="page cae-result-page"><div class="container"><div class="breadcrumb"><NuxtLink to="/cae">CAE 仿真</NuxtLink><ChevronRight :size="14"/><span>{{task.id}}</span></div><header class="cae-result-head"><div><span class="status-badge success"><CheckCircle2 :size="15"/>计算完成</span><h1>{{task.params.case_name || task.toolName}}</h1><p>{{task.id}} · {{result.solver}} · {{task.duration}} ms</p></div><button class="button" @click="downloadJson"><FileJson :size="16"/>导出结果</button></header><section class="cae-summary"><div v-for="item in result.summary" :key="item.label"><small>{{item.label}}</small><strong>{{typeof item.value==='number'?Number(item.value).toPrecision(6):item.value}}</strong><span>{{item.unit}}</span></div></section><div class="cae-result-layout"><main><div class="viewport-toolbar"><div><strong>结果场与变形</strong><span>按真实求解数据绘制</span></div></div><CaeViewport :kind="task.tool" stage="results" :params="task.params as Record<string,number>" :result="result as any"/></main><aside><div class="studio-panel-title"><ShieldCheck :size="16"/><strong>验证检查</strong></div><div class="cae-check-list"><div v-for="check in result.checks" :key="check.id" :class="check.status"><CheckCircle2 v-if="check.status==='pass'" :size="16"/><AlertTriangle v-else :size="16"/><span><strong>{{check.label}}</strong><small>{{check.message}}</small></span><b>{{Number(check.value).toExponential(2)}} {{check.unit}}</b></div></div></aside></div><div v-if="result.warnings.length" class="inline-alert warning"><AlertTriangle :size="18"/><div><strong>适用范围提示</strong><p v-for="warning in result.warnings" :key="warning">{{warning}}</p></div></div></div></div>
  <div v-else class="page"><div class="container empty-state"><AlertTriangle :size="38"/><h1>没有找到这个 CAE 分析</h1><p>分析类型或任务记录不存在。</p><NuxtLink to="/cae" class="button">返回 CAE 模块</NuxtLink></div></div>
</template>
